  "content": "import json, sys, time, concurrent.futures
sys.path.insert(0, '/workspace/submission'); sys.path.insert(0, '/workspace')
from research_sdk import Client
import graders

manifest = json.load(open('/workspace/submission/evaluation.json'))
prompts = {q["id"]: q["prompt"] for q in manifest["questions"]}
g = graders.make_graders()
PILOT = ["m00", "h00", "c25", "w03", "c01", "d05"]
MODELS = ["development-01", "development-06", "development-08", "development-12"]

def run_pair(pair):
    model, iid = pair
    c = Client()
    mt = 16384 if iid.startswith("m") else 8192
    t0 = time.time()
    try:
        res = c.item(iid, prompts[iid], g[iid], model=model, max_tokens=mt)
    except Exception as e:
        return {"model": model, "id": iid, "err": str(e)[:300]}
    dt = time.time() - t0
    return {"model": model, "id": iid, "score": res.get("score"),
            "ex": res.get("execution_status"), "ans": res.get("answer_status"),
            "finish": res.get("finish_reason"), "secs": round(dt),
            "out_chars": len(res.get("evidence") and "" or "")}

pairs = [(m, i) for m in MODELS for i in PILOT]
out = []
with concurrent.futures.ThreadPoolExecutor(max_workers=8) as ex:
    for r in ex.map(run_pair, pairs):
        out.append(r); print(json.dumps(r), flush=True)
json.dump(out, open('/workspace/build/pilot1_results.json', 'w'), indent=1)
"
